    fullDescription: 'لمّا بلغ النبي ﷺ الثانية عشرة من عمره، خرج مع عمّه أبي طالب في قافلة تجارية متّجهة نحو بُصرى في الشام. وكان هذا أول خروج له خارج حدود الجزيرة العربية، وكانت فيه إشارات إلهية دالّة على مكانته عند الله قبل أن يُعلَن عن نبوّته.\n\nوحين مرّت القافلة بالقرب من دير بُحيرى في بُصرى، لاحظ الراهب النصراني العالم بُحيرى ظاهرةً لفتت انتباهه: غمامة تسير مع القافلة تُظلّ فتىً واحداً من بين الجميع. فنزل من ديره وعرض الضيافة على القافلة كلها، ثم تفرّس في وجوه الجميع حتى وجد الفتى محمداً، فتحقّق مما كان يقرأه في كتبه القديمة من صفات النبي الموعود.\n\nفجلس بُحيرى إلى جانبه وبدأ يسأله أسئلة دقيقة، وطلب أن ينظر إلى ظهره فوجد خاتم النبوّة بين كتفيه، وهو شامة بارزة كانت موصوفة في الكتب. ثم التفت إلى أبي طالب وقال بجدية وحرارة: "ارجع بابن أخيك إلى بلده، واحذر عليه اليهود؛ فوالله لئن رأوه وعرفوا منه ما عرفتُ ليبغُنّه شراً، فإنه كائن لهذا الغلام شأن عظيم."\n\nفأسرع أبو طالب بالعودة بابن أخيه إلى مكة استجابةً لهذه النصيحة الصادقة من رجل لا يعرفه ولا مصلحة له في الكذب. وقد كان في هذه الحادثة شاهد من أهل الكتاب على نبوّة محمد ﷺ قبل أن يُبعث، مصداقاً لقوله تعالى: ﴿الَّذِينَ آتَيْنَاهُمُ الْكِتَابَ يَعْرِفُونَهُ كَمَا يَعْرِفُونَ أَبْنَاءَهُمْ﴾.',
