    fullDescription: 'قبل البعثة النبوية بنحو عشرين عاماً، شهدت مكة المكرمة حدثاً ترك أثراً في نفس الشاب محمد ﷺ بقي حاضراً حتى بعد الإسلام. جاء رجل من اليمن ـ من قبيلة زبيد ـ بتجارة إلى مكة، فاستولى عليها العاصي بن وائل السهمي دون وجه حقّ، ولمّا طالبه الزبيدي بماله رفض وأعرض عنه. فصاح الزبيدي بأعلى صوته في أندية قريش ومجامعها مُستنجداً بأهل الشرف والمروءة.\n\nفاجتمع في دار عبدالله بن جدعان التيميّ سادةُ قريش من بني هاشم وبني المطلب وبني زهرة وبني تيم وبني الحارث، وتعاهدوا وتحالفوا على أن لا يجدوا مظلوماً في مكة إلا نصروه ورددوا إليه حقّه، وعلى أن لا يُمكَّن ظالم من ظلمه. ثم ذهبوا جميعاً إلى العاصي بن وائل وانتزعوا من يده حقّ الزبيدي وأعادوه إليه.\n\nوقد شهد النبي ﷺ هذا الحلف المبارك وكان في العشرين من عمره تقريباً، فبقي في نفسه الكريمة أثره العميق. وحين سُئل عنه بعد الإسلام، قال ﷺ قولته الخالدة: "لقد شهدتُ في دار عبدالله بن جدعان حلفاً لو دُعيتُ إليه في الإسلام لأجبتُ، وهو أن تُردّ الحقوق إلى أهلها وألا يُعدى على أحد." فكان ذلك دليلاً على أن الإسلام لا يُلغي كلّ ما كان في الجاهلية، بل يُقرّ ما وافق الحقّ والعدل منه.\n\nوفي هذا الموقف من شبابه ﷺ شاهد على طبيعته الفطرية النقية التي كانت تنحاز دائماً لجانب المظلوم وتأبى الظلم والعدوان، حتى إن قومه سمّوه قبل البعثة بالصادق الأمين تقديراً لخُلقه وسلامة فطرته.',
