    fullDescription: 'السيدة خديجة بنت خويلد بن أسد القرشية رضي الله عنها سيدة قريش الكريمة ذات المال والشرف والجمال. كانت تُرسل تجارتها مع الرجال الثقات، فلمّا بلغها صدق محمد بن عبدالله وأمانته وحسن خُلقه، عرضت عليه أن يخرج بتجارتها إلى الشام مع غلامها ميسرة. فخرج ﷺ وهو في الخامسة والعشرين من عمره وعاد بربح وافر، فأُعجبت خديجة بما حكاه ميسرة من فضله وحسن سلوكه.\n\nثم عرضت عليه الزواج بواسطة صديقتها نفيسة بنت منية، فقبل ﷺ وتمّ العقد بمهر أدّاه عنه عمّه أبو طالب، وكان عمره خمساً وعشرين سنة وعمرها أربعين سنة. فكان زواجاً فريداً في تاريخ الزيجات: امرأة في ريعان نضجها وحكمتها تختار رجلاً في إبان شبابه لما رأت فيه من الفضل والنبل.\n\nوقد كانت خديجة رضي الله عنها أول من آمن بالرسالة من الرجال والنساء جميعاً. وحين جاء النبي ﷺ من غار حراء يرتجف وقلبه يتقطّع وجداً وخوفاً، كانت خديجة أول المطمئِنين لروعه، إذ قالت بثقة ثابتة: "والله لا يُخزيك الله أبداً، إنك لتصل الرحم، وتصدق الحديث، وتحمل الكلّ، وتكسب المعدوم، وتَقري الضيف، وتُعين على نوائب الحق." فكانت هذه الكلمات أول سند إنساني يدعمه في أصعب لحظة مرّت عليه.\n\nوقد أحبّها النبي ﷺ حبّاً لم يُشاركها فيه سواها طوال حياتها، فلم يتزوج عليها خمسةً وعشرين عاماً. وبعد وفاتها ظلّ يذكرها ويُكثر الثناء عليها ويبعث بالهدايا إلى صديقاتها تكريماً لذكراها. وقد بشّرها جبريل عليه السلام في حياتها ببيت في الجنة من قصب لا صخب فيه ولا نصب، شرفاً لا يُدانيه شرف.',
