    fullDescription: 'في السنة الخامسة والثلاثين من عمر النبي ﷺ، أقدمت قريش على إعادة بناء الكعبة المشرفة بعد أن تهدّمت جدرانها بسيل جارف وحريق. وحين وصل العمّال إلى موضع الحجر الأسود المقدّس، اشتعلت نار النزاع بين القبائل؛ إذ أرادت كلّ قبيلة الشرف الأعظم بأن تضع الحجر بيدها، حتى كادت السيوف تُسلّ والدماء تُراق، وأمضوا في تنازعهم أربعة أيام أو خمسة.\n\nفأشار أحد كبارهم بأن يجعلوا الحكم لأول من يدخل من باب المسجد. فكان أول الداخلين محمد بن عبدالله ﷺ، فلما رأوه هتفوا بصوت واحد: "هذا الأمين! رضينا به حكماً!" فتقدّم ﷺ بهدوء ورويّة، وطلب ردًا وثوبا فأُحضر له، ثم وضع الحجر الأسود في وسطه، وأمر زعيم كل قبيلة أن يُمسك بطرف من أطراف الثوب. فرفعوه جميعاً في مشهد موحِّد، حتى إذا حاذى الحجر موضعه المقدّس، أمسك النبي ﷺ به بيده الكريمة ووضعه في مكانه.\n\nوكانت هذه الحادثة التي وقعت قبل البعثة بخمس سنوات شاهداً ناطقاً على أن قريشاً كانت ترى في محمد ﷺ الحكم العادل المقبول الذي لا يجامل ولا ينحاز. وفيها دلالة إلهية على أن الله كان يُعدّ هذا الرجل ليكون حكماً بين الناس جميعاً، لا بين قبائل قريش وحدها.\n\nوقد حمل النبي ﷺ الحجر الأسود بيده وهو في سنّ الفتوّة والقوة، ثم حمله مرةً أخرى يوم فتح مكة حين طاف وكان يستلمه في طوافه، ويُذكّرنا كلّ ذلك بأن الكعبة المشرفة كانت محوراً في حياته من لحظة ولادته إلى ساعة فتح مكة.',
