    fullDescription: 'في شهر رمضان المبارك من العام العاشر قبل الهجرة، وكان النبي ﷺ قد بلغ أربعين سنةً كاملة، وكان يتعبّد في غار حراء على جبل النور قرب مكة المكرمة، يأوي إليه أسابيع يتأمّل ويتحنّث بعيداً عن ضجيج الجاهلية وأوثانها. وفي تلك الليلة المباركة التي نسمّيها ليلة القدر، جاءه جبريل عليه السلام في صورته المهيبة فأخذه وضمّه ضمّاً شديداً حتى بلغ منه الجهد، ثم أرسله وقال: "اقرأ."\n\nقال النبي ﷺ: "ما أنا بقارئ." فأخذه الملك مرةً ثانية وضمّه أشدّ من الأولى ثم أرسله وقال: "اقرأ." قال: "ما أنا بقارئ." فأخذه الثالثة وضمّه ثم أرسله وقال: ﴿اقْرَأْ بِاسْمِ رَبِّكَ الَّذِي خَلَقَ، خَلَقَ الْإِنسَانَ مِنْ عَلَقٍ، اقْرَأْ وَرَبُّكَ الْأَكْرَمُ، الَّذِي عَلَّمَ بِالْقَلَمِ، عَلَّمَ الْإِنسَانَ مَا لَمْ يَعْلَمْ﴾. فكانت هذه أول خمس آيات نزلت من القرآن الكريم على قلب النبي ﷺ.\n\nعاد النبي ﷺ إلى بيته يرتجف قلبه ويعتريه الرعب مما رأى وسمع، فقال لخديجة: "زمّلوني زمّلوني." فزمّلوه حتى ذهب عنه الروع. ثم أخبر خديجة بما جرى فطمأنته بكلماتها الخالدة التي حفظها التاريخ. ثم ذهبت به إلى ابن عمّها ورقة بن نوفل العالم بالكتب القديمة، فلمّا سمع ورقة القصة صاح: "هذا الناموس الذي أنزل الله على موسى! يا ليتني فيها جَذَعاً، ليتني أكون حياً إذ يُخرجك قومك!"\n\nوكان نزول الوحي في غار حراء إيذاناً بانطلاق أعظم رسالة عرفتها البشرية، وكان افتتاح الوحي بـ"اقرأ" دلالةً صريحة على أن الإسلام دين العلم والمعرفة، في أمة كانت تغرق في الجهل والأمية. وقد بقيت هذه الآيات الخمس الأولى مضيئةً في صدر التاريخ شاهدةً على لحظة بدأت فيها الدنيا تنقلب إلى ما هي عليه اليوم.',
