    fullDescription: 'بعد نزول الوحي على النبي ﷺ في غار حراء، انطلقت الدعوة الإسلامية في سرية تامة لمدة ثلاث سنوات. كانت الحكمة الإلهية تقضي بالتمهيد والبناء القاعدي قبل المواجهة العلنية مع مجتمع جاهلي راسخة فيه عبادة الأوثان منذ قرون. فانطلق النبي ﷺ يدعو أقرب الناس إليه ممن يثق بهم ويعرف صفاءهم.\n\nأول من أسلمت السيدة خديجة بنت خويلد رضي الله عنها دون تردد في اللحظة ذاتها التي أخبرها النبي ﷺ بما نزل عليه. وكان علي بن أبي طالب رضي الله عنه أول الصبيان إسلاماً وعمره نحو عشر سنوات، وكان ينام في كنف النبي ﷺ. وأسلم زيد بن حارثة مولى النبي ﷺ وأحبّه. أما أبو بكر الصديق رضي الله عنه فكان أول الرجال الأحرار إسلاماً، إذ لم يتردد حين عرض عليه النبي ﷺ الإسلام بل بادر بالتصديق الفوري.\n\nوكان أبو بكر رضي الله عنه داعيةً عظيماً دفعته محبته للإسلام إلى دعوة خلانه وأصدقائه، فجاء بعثمان بن عفان والزبير بن العوام وطلحة بن عبيدالله وسعد بن أبي وقاص وعبد الرحمن بن عوف. وكان هؤلاء نواة الصحابة الكرام الذين سيحملون الرسالة وينشرونها في الآفاق.\n\nوكان النبي ﷺ يجتمع بالمسلمين الأوائل في دار الأرقم بن أبي الأرقم المخزومي عند جبل الصفا، بعيداً عن أعين قريش، يُعلّمهم القرآن الكريم ويُرسّخ في قلوبهم أسس العقيدة. واستمرت هذه المرحلة السرية نحو ثلاث سنوات كاملة، جُمِع فيها نفر من أشرف الناس قبل أن يُؤمَر بالجهر بالدعوة.',
