    description:
      'بعد ثلاث سنوات من الدعوة السرية، أُمر ﷺ بالجهر. صعد جبل الصفا ونادى: "يا صباحاه!" فاجتمعت قريش. قال: "أرأيتم لو أخبرتكم أن خيلاً بالوادي تريد أن تُغير عليكم أكنتم مصدقيّ؟" قالوا: نعم. قال: "فإني نذير لكم بين يدي عذاب شديد." فصاح أبو لهب: "تباً لك!" فنزلت سورة المسد.',
    fullDescription: 'بعد ثلاث سنوات من الدعوة السرية التي رسّخ فيها النبي ﷺ العقيدة في نفوس أصحابه الأوائل، نزل عليه الأمر الإلهي الحاسم: ﴿فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ﴾. وكانت هذه لحظة التحوّل الكبرى في مسيرة الدعوة، إذ انتقلت من السرّ إلى العلن ومن الخاصة إلى العامة.\n\nصعد النبي ﷺ إلى جبل الصفا وأطلق نداء "يا صباحاه!" وهو النداء العربي التقليدي الذي كان يُرفع إنذاراً من خطر داهم، فأسرعت قريش من كل ناحية. ثم استحضر شهادتهم على صدقه المعروف عندهم قبل أن يُبلّغهم، فقال: "أرأيتم لو أخبرتكم أن خيلاً بالوادي تريد أن تُغير عليكم، أكنتم مصدّقيّ؟" قالوا بالإجماع: "نعم، ما جرّبنا عليك كذباً." فانتهز الفرصة وقال: "فإني نذير لكم بين يدي عذاب شديد."\n\nوكان ردّ الفعل متفاوتاً؛ فأكثر القوم نظروا إليه دهشةً ثم انصرفوا، أما عمّه أبو لهب فصاح في وجهه صيحة حقد: "تباً لك! أهذا جمعتنا له؟" فكانت ردّة فعله صريحة وفاجرة، فأنزل الله فيه سورة المسد كاملة رداً على تلك الصيحة، وهي أول سورة تتناول شخصاً بعينه بالاسم.\n\nوقد أعقب هذا الإعلان موجة من الأذى والسخرية والاضطهاد، فبدأ كبراء قريش يُحرّضون على المسلمين ويُعذّبون من لا حماية لهم من الموالي والضعفاء. غير أن النبي ﷺ ثبت على موقفه صابراً محتسباً، مستمدّاً قوّته من الوعد الإلهي بأن الحق سيعلو مهما طال الزمن.',
    verse: 'فَاصْدَعْ بِمَا تُؤْمَرُ وَأَعْرِضْ عَنِ الْمُشْرِكِينَ',
    verse_ref: 'الحجر: 94',
