      'اشتد أذى قريش على المسلمين، فأمر النبي ﷺ أصحابه بالهجرة إلى الحبشة. هاجر نحو ثمانين رجلاً وامرأة. مثَل جعفر بن أبي طالب أمام النجاشي وتلا عليه سورة مريم، فبكى النجاشي حتى بلّت دموعه لحيته وقال: "ما يبعد هذا عما جاء به عيسى من المشكاة ذاتها."',
    fullDescription: 'لمّا اشتدّ أذى قريش على المسلمين وضاقت بهم السبل في مكة المكرمة، أذن النبي ﷺ لأصحابه بالهجرة إلى الحبشة قائلاً: "إن بها ملكاً لا يُظلَم عنده أحد." فكانت الهجرة الأولى خفيةً في جماعة صغيرة بلغت خمسة عشر شخصاً، ثم تلتها الهجرة الثانية الأكبر التي ضمّت نحو مئة وعشرة أشخاص أو أكثر.\n\nوأرسلت قريش مبعوثَيها عمرو بن العاص وعبدالله بن أبي ربيعة بالهدايا إلى النجاشي وقادته لاستعادة المهاجرين، فاستجاب النجاشي للعدالة وأصغى إلى الطرفين. فوقف جعفر بن أبي طالب رضي الله عنه خطيباً عن المسلمين وأجاد كل الإجادة؛ شرح للنجاشي حال العرب قبل الإسلام وما أصلحه الإسلام، ثم تلا عليه مطلع سورة مريم في وصف مريم وعيسى عليهما السلام.\n\nفبكى النجاشي الملك الكريم حتى بلّت دموعه لحيتَه وبكى رجاله من حوله، وقال: "ما يبعد هذا عمّا جاء به عيسى مثل هذا." وأبى أن يُسلّم المهاجرين إلى قريش قائلاً: "اذهبوا فأنتم سيوم بأرضي، من سبّكم غُرِّم. ما أُحبّ أن يكون لي دبري الذهب وأنني آذيتُ رجلاً منكم." فرجع مبعوثا قريش خائبَين.\n\nوقد أسلم النجاشي أصحمة رحمه الله سرّاً وكتب بإسلامه إلى النبي ﷺ، فلمّا بلغ النبيَّ ﷺ نبأُ وفاته خرج إلى المصلّى وصلّى عليه صلاة الغائب، وهو أمر فريد في تاريخ الإسلام يدلّ على مكانة النجاشي العظيمة. وكانت هجرة الحبشة أول دليل عملي على أن الإسلام رسالة عالمية تتجاوز حدود الجزيرة العربية.',
