    fullDescription: 'كان حمزة بن عبد المطلب رضي الله عنه عمّ النبي ﷺ وأخاه من الرضاعة، وكان من أشد فتيان قريش بأساً وأشجعهم وأشرفهم نفساً، لا يهاب أحداً ولا يخشى لومة لائم. وفي السنة السادسة من البعثة تقريباً، خرج ذات يوم إلى الصيد كعادته، فلمّا عاد وجد جاريةً لعبدالله بن جدعان تُخبره أن أبا جهل لقي محمداً ﷺ عند الصفا وآذاه أذىً شديداً وسبّه ووبّخه وهو لا يُردّ.\n\nفاشتعل في قلب حمزة غضب شديد وأخذته الحميّة لابن أخيه، فتوجّه مسرعاً إلى المسجد الحرام حيث كان أبو جهل جالساً في نادي قريش. فضربه بقوسه في رأسه ضربةً أدمته أمام الملأ وقال بصوت عالٍ مسمَع: "أتشتمه وأنا على دينه أقول ما يقول؟ فاردُد ذلك إن استطعتَ!" فلم يجرؤ أحد على التدخل وكان أبو جهل يعلم أن حمزة ليس ممن يُزاح.\n\nثم توجّه حمزة إلى النبي ﷺ فأعلن إسلامه، وثبّت الله إسلامه في قلبه، فأصبح مؤمناً صادق الإيمان. وكان أثر إسلامه فورياً وعظيماً؛ إذ هابت قريش جانب المسلمين وعلمت أن بينهم الآن أسداً لا يُستهان به. وقد سمّاه النبي ﷺ "أسد الله وأسد رسوله" تقديراً لشجاعته وصدق إيمانه.\n\nوكان مآل هذا الأسد الكريم أن يلقى ربّه شهيداً في غزوة أُحد عام 625م بعد أن قاتل قتالاً منقطع النظير، فسمّاه النبي ﷺ "سيّد الشهداء" وبكى عليه بكاءً حاراً حين رأى ما فُعل بجسده الكريم.',
