    description:
      'كان عمر بن الخطاب من أشد الناس عداوةً للإسلام. خرج يوماً يريد قتل النبي ﷺ فأُخبر بأن أخته فاطمة وزوجها سعيداً أسلما. فذهب إليهما غاضباً فضرب سعيداً وآذى أخته. ثم سمع ما تقرآنه من سورة طه فلان قلبه. أخذ الصحيفة وقرأها ثم قال: "دلوني على محمد." فأتى النبي ﷺ وأعلن إسلامه، فكبّر المسلمون في المسجد الحرام أول مرة تكبيرة دوّت في أرجاء مكة.',
    fullDescription: 'كان عمر بن الخطاب رضي الله عنه في الجاهلية شديد العداوة للإسلام والمسلمين، يُرعب كلّ من يعلم بإسلامه. وفي السنة السادسة من البعثة تقريباً، خرج يوماً شاهراً سيفه عازماً على قتل النبي ﷺ ليُريح قريشاً مما فرّقها. فلقيه رجل في طريقه فقال له: "ابدأ بأهل بيتك، فإن أختك وزوجها قد أسلما." فاشتعل غيظاً وتوجّه إلى بيت أخته فاطمة بنت الخطاب وزوجها سعيد بن زيد.\n\nطرق الباب فأخفيا الصحيفة وفتحا له وبداخلهما الخوف. فدخل وسألهما عمّا كانا يقرآن فأنكرا. فضرب سعيداً وآذى أخته حتى رأى الدم على وجهها، فصاحت به: "نعم أسلمنا وآمنّا بالله ورسوله فاصنع ما شئت." فوقفت هذه المرأة الشجاعة في وجه أخيها الجبّار ببسالة نادرة.\n\nفوجد عمر في نفسه شيئاً من الخجل، وطلب أن يرى الصحيفة فناولته إياها. فأخذها وقرأ أوّل سورة طه: ﴿طه، مَا أَنزَلْنَا عَلَيْكَ الْقُرْآنَ لِتَشْقَىٰ﴾ فانتقل من سطر إلى سطر وكلامه الإلهي يتسرّب إلى عقله وقلبه كالضوء في الظلام. فلمّا بلغ قوله تعالى: ﴿إِنَّنِي أَنَا اللَّهُ لَا إِلَٰهَ إِلَّا أَنَا فَاعْبُدْنِي﴾، خشعت نفسه وقال: "دلّوني على محمد."\n\nفذهب إلى دار الأرقم حيث كان النبي ﷺ مع أصحابه. وحين أُخبر النبيُّ ﷺ بإسلام عمر قال: "اللهم أعزّ الإسلام بعمر بن الخطاب." فدخل عمر رضي الله عنه وأعلن إسلامه، فكبّر المسلمون تكبيرة دوّت في سماء مكة. وكان أول ما طلبه عمر أن يُعلن إسلامه جهاراً ويصلّي عند الكعبة أمام الناس، فكان ذلك نقطة تحوّل كبرى في تاريخ الدعوة.',
