    description:
      'اجتمعت قريش وكتبت صحيفة ظالمة تقضي بمقاطعة بني هاشم وبني المطلب اقتصادياً واجتماعياً، ونُصّ فيها على منع البيع والشراء منهم ومنع مصاهرتهم حتى يُسلّموا النبي ﷺ. فانحاز بنو هاشم إلى شعبهم ثلاث سنوات كاملة. جاعوا حتى أكلوا الورق والجلود. وأنزل الله الأرضة على الصحيفة فأكلت كل ما فيها إلا اسم الله، فجاء النبي ﷺ وأخبر عمه أبا طالب فذهب وأخبر قريشاً، فتفرّق الحلف وانتهى الحصار.',
    fullDescription: 'في السنة السابعة من البعثة تقريباً، تداعت قريش وكتبت صحيفةً ظالمة معلّقة في جوف الكعبة، تقضي بمقاطعة بني هاشم وبني المطلب مقاطعةً شاملة: لا بيع معهم ولا شراء، ولا مصاهرة ولا تزاوج، ولا كلام ولا سلام، حتى يُسلّموا محمداً ﷺ للقتل أو يتبرّأوا منه. فانحاز بنو هاشم وبنو المطلب مؤمنهم وكافرهم إلى شعب أبي طالب، وكان وادياً ضيّقاً في أطراف مكة.\n\nومضت ثلاث سنوات عجاف في ذلك الشِّعب الضيّق، والمسلمون يُعانون ضروب الشدّة: الجوع الذي بلغ حداً كانوا فيه يأكلون الورق والجلود وجلد الميتة، والمرض الذي فتك بالضعفاء والأطفال، والحرّ في الصيف والبرد في الشتاء دون عزل كافٍ. وكانت تُسمع في الشعب بالليل أصوات بكاء الأطفال من الجوع فيُشجي سامعيها.\n\nوكان بعض أهل الخير من قريش يُدخلون الطعام سرّاً في الليل رحمةً بالمحاصَرين، كهشام بن عمرو الذي كان يشدّ بعيره بالطعام ويُرسله ليلاً إلى الشعب. ثم أطلع الله نبيّه ﷺ على أن الأرضة قد أكلت الصحيفة فلم يبقَ منها إلا ما كان فيه اسم الله. فأخبر النبي ﷺ عمّه أبا طالب بذلك، فذهب أبو طالب إلى قريش مُتحدّياً وطلب أن تُفتح الصحيفة فتُفتح فإن كان ما قال ابن أخيه حقاً رُفع الحصار.\n\nففُتحت الصحيفة المعلّقة فوجدوها مأكولة إلا اسم الله تعالى، فكانت آيةً أخزتهم وفرّقت الحلف، وانتهى الحصار. وفي هذه المحنة الثلاثية درس عظيم: أن الصبر الجماعي على الأذى واجب حين يكون الثبات على الحق في الميزان.',
