    fullDescription: 'في السنة العاشرة من البعثة، توالت على النبي ﷺ مصيبتان في أشهر معدودة، وكلٌّ منهما وحدها كانت تكفي لتُثقل قلب أيّ إنسان. فقد رحل عمّه أبو طالب سيّد قريش ومَن لا تجرؤ على أذى ابن أخيه في وجوده، ثم أعقبه بأسابيع رحيل خديجة رضي الله عنها أمّ المؤمنين وأول المصدّقين والسند الأوثق.\n\nوقد سمّى المؤرخون هذا العام "عام الحزن" لأن المسلمين فقدوا في وقت واحد سنداً بشرياً لا يُعوَّض. وتجرّأت قريش بعد وفاة أبي طالب على النبي ﷺ تجرّؤاً لم تكن تُقدم عليه من قبل؛ حتى إن سفيهاً منهم صبّ التراب على رأسه الشريف في الطريق. فجاء إلى بيته والغبار على رأسه فوجد ابنته فاطمة تبكي وتغسله، فقال لها بثقة المتوكل: "لا تبكي يا بنيتي، فإن الله مانع أباك."\n\nوقد حاول النبي ﷺ بعد عام الحزن أن يجد ملاذاً جديداً لدعوته فخرج إلى الطائف ليطلب من ثقيف النصرة، فكان ما كان من الردّ القاسي والأذى المؤلم. غير أن الله عوّضه عن حزن الأرض بكرامة السماء حين أسرى به إلى المسجد الأقصى وعرج به إلى السماوات العلى في ليلة الإسراء والمعراج المباركة.\n\nوفي عام الحزن درس إلهي عميق مفاده أن الله حين يُقلّل الأسباب البشرية يُعوّض عنها بتوثيق الصلة بين العبد وربّه مباشرةً دون واسطة. فكانت محنة العام مقدمةً للكرامة الربانية التي لا يُشاركه فيها أحد من خلقه.',
