    description:
      'بعد وفاة خديجة وأبي طالب، ذهب النبي ﷺ ماشياً إلى الطائف مسافة ثمانين كيلاً وحده مع مولاه زيد بن حارثة يطلب نصرة ثقيف. فاستقبله زعماؤهم باستهزاء ثم أغروا سفهاءهم وعبيدهم برميه بالحجارة حتى أدموا قدميه. فجلس ﷺ تحت ظل شجرة ودعا بدعاء أشجى: "اللهم إليك أشكو ضعف قوتي وقلة حيلتي وهواني على الناس..." فأرسل الله ملَك الجبال يعرض عليه أن يطبق الأخشبين على أهل مكة والطائف فقال: "بل أرجو أن يُخرج الله من أصلابهم من يعبده."',
    fullDescription: 'بعد أن فقد النبي ﷺ في عام واحد سند قلبه خديجة وسند ظهره أبا طالب، خرج يبحث عن سند جديد في الطائف يُقيم فيه دعوته. سار ماشياً مع مولاه زيد بن حارثة نحو ثمانين كيلومتراً جنوب مكة يريد ثقيفاً عشرة أيام. فلمّا لقي زعماءهم الثلاثة — بني عمرو بن عمير — استقبلوه استقبال السخرية والاستهزاء، وقال أحدهم: "أما وجد الله أحداً غيرك؟" وقال آخر: "لا أُكلّمك كلمةً واحدة إن كنتَ نبياً."\n\nثم أغروا سفهاءهم وعبيدهم وصبيانهم بمطاردته في شوارع الطائف يرمونه بالحجارة على ساقيه وقدميه، حتى امتلأت نعلاه بالدم. ولجأ النبي ﷺ إلى حائط لعتبة وشيبة ابني ربيعة، فجلس تحت ظل كرمة وعيناه تدرفان، وهناك خرجت من قلبه المحبوس تلك الكلمات التي هي من أعمق أدعية التاريخ الإنساني:\n\n"اللهم إليك أشكو ضعف قوتي وقلة حيلتي وهواني على الناس، يا أرحم الراحمين، أنت ربّ المستضعفين وأنت ربّي، إلى من تكلني؟ إلى بعيد يتجهّمني أم إلى عدو ملّكته أمري؟ إن لم يكن بك عليّ غضب فلا أبالي، غير أن عافيتك هي أوسع لي..."\n\nفأرسل الله إليه جبريل ومعه ملَك الجبال يعرض عليه أن يُطبق الأخشبين على أهل مكة والطائف فيُهلكهم، فقال ﷺ بسعة صدر تفوق الوصف: "بل أرجو أن يُخرج الله من أصلابهم من يعبد الله وحده لا يُشرك به شيئاً." فكانت هذه اللحظة من أبلغ شواهد رحمته ﷺ وسعة أفقه وعُمق توكّله على الله.',
