    description:
      'في ليلة مباركة أُسري بالنبي ﷺ من المسجد الحرام إلى المسجد الأقصى على البراق، ثم عُرج به إلى السماوات السبع. كلّمه ربه وفُرضت عليه الصلوات الخمس. رأى جبريل على صورته الحقيقية له ستمئة جناح. آمن أبو بكر حين وصف لهم المسجد الأقصى بدقة فسُمّي "الصديق".',
    fullDescription: 'في ليلة مباركة من ليالي السنة العاشرة من البعثة ـ وقد قيل إنها السابع والعشرون من رجب ـ أُسري بالنبي ﷺ جسداً وروحاً بيقظة لا مناماً في رحلة كانت جزاءً إلهياً لعبده المحزون ومنحةً ربّانية لا يُقدَّر قدرها. جاءه جبريل عليه السلام وأتى بالبراق ـ دابة بيضاء بين البغل والحمار تضع حافرها عند منتهى طرفها ـ فركبها النبي ﷺ وطارت به من المسجد الحرام إلى المسجد الأقصى في لمح البصر.\n\nوفي المسجد الأقصى المبارك، جُمع الأنبياء جميعاً فأمّهم النبي ﷺ إماماً فيهم، وكان في ذلك إعلان لخاتمية رسالته وإمامته لإخوانه من الأنبياء والرسل. ثم انطلق به جبريل عليه السلام عرَجاً إلى السماوات السبع، ففي كل سماء لقي نبياً كريماً يُرحّب به: آدم في الأولى، ويحيى وعيسى في الثانية، ويوسف في الثالثة، وإدريس في الرابعة، وهارون في الخامسة، وموسى في السادسة، وإبراهيم في السابعة.\n\nثم عرج به إلى ما فوق السماوات وكلّمه ربّه تبارك وتعالى وفرض عليه خمسين صلاة، فلم يزل موسى عليه السلام يُشير عليه بطلب التخفيف وهو يرجع إلى ربّه مراراً حتى صارت خمساً في العدد وخمسين في الأجر والثواب. ثم رأى جبريل عليه السلام على صورته الحقيقية له ستّمئة جناح سادّ الأفق. ورأى النبي ﷺ الجنة والنار وعجائب الملكوت الإلهي.\n\nعاد النبي ﷺ قبل الفجر وأخبر قريشاً فكذّبه أكثرهم وقالوا: نحن نضرب أكباد الإبل شهراً ذهاباً وإياباً إلى المسجد الأقصى وأنت تدّعي أنك ذهبتَ ليلةً واحدة؟ وذهب بعضهم إلى أبي بكر يُخبره فقال قبل أن يسأله: "إن كان قال ذلك فقد صدق، أنا أُصدّقه بأبعد من ذلك." فلُقّب بالصديق.',
