    description:
      'في موسم الحج، لقي النبي ﷺ اثني عشر رجلاً من الخزرج والأوس في العقبة فبايعوه على ألا يشركوا بالله شيئاً ولا يسرقوا ولا يزنوا ولا يقتلوا أولادهم. فبعث معهم مصعب بن عمير أول سفير في الإسلام يُعلّمهم القرآن ويدعو إلى الإسلام في يثرب. وأسلم على يديه في العام الواحد أُسيد بن حضير وسعد بن معاذ وبذلك تحوّل اتجاه الإسلام نحو المدينة.',
    fullDescription: 'في موسم الحج من العام الحادي عشر من البعثة، كان النبي ﷺ يعرض دعوته على القبائل الوافدة إلى مكة كعادته، فلقي اثني عشر رجلاً من يثرب جاؤوا في موسم الحج، ستة منهم من الخزرج وستة من الأوس. فدعاهم النبي ﷺ إلى الإسلام فأجابوه وأسلموا، وبايعوه عند العقبة بيعتهم الأولى.\n\nوكانت بنود هذه البيعة تركّز على الجانب الأخلاقي والعقدي: ألا يُشركوا بالله شيئاً، ولا يسرقوا، ولا يزنوا، ولا يقتلوا أولادهم، ولا يأتوا ببهتان يفترونه، ولا يعصوه في معروف. فكانت هذه البيعة بيعة التزام شخصي قبل أن تكون بيعة حماية ودفاع.\n\nوتبصّر النبي ﷺ أهمية هذا الحدث وفرصته الذهبية، فأرسل معهم مصعب بن عمير رضي الله عنه الشاب القرشي الذي تربّى في النعيم فترك كل شيء للإسلام. فكان مصعب أول سفير في تاريخ الإسلام، يُعلّم الناس القرآن الكريم ويدعوهم إلى الله بحكمة وبصيرة.\n\nوفي ظرف عام واحد فقط، أحدث مصعب بن عمير ثورةً في يثرب؛ إذ أسلم على يديه سيّد الأوس سعد بن معاذ وسيّد بني عبد الأشهل أُسيد بن حضير، فعادا إلى قبيلتيهما فلم يبقَ فيهما أحد إلا أسلم. وكانت هذه البذرة التي زرعها مصعب هي التي أنبتت شجرة الأنصار العظيمة التي صنعت الهجرة والدولة الإسلامية.',
