    fullDescription: 'لمّا دخل النبي ﷺ المدينة المنورة كانت أولى همومه أن يُؤسّس داراً للعبادة تجتمع فيها الأمة وتنبثق منها الدولة. فأمر بإرخاء زمام ناقته وتُركت تسير حيث شاءت حتى بركت عند أرض كانت لغلامين يتيمين من بني النجار تُسمّى سهلاً وسهيلاً أو مالاً وما نحوه.\n\nفعرض النبي ﷺ على الغلامين شراء الأرض فأبيا وأصرّا على أنها هبة لله ورسوله، فأبى ﷺ إباءً تاماً أن يأخذها مجاناً وأصرّ على دفع ثمنها العادل، وأمر أبا بكر بدفع عشرة دنانير ثمناً لها. وفي هذا الموقف درس عظيم في احترام الملكية الخاصة ورفض الأخذ بغير حقّ حتى ولو كان الأمر بالتراضي.\n\nثم بدأ البناء بأيدي النبي ﷺ وأصحابه جميعاً، يتساوى فيه المهاجر والأنصاري والسيّد والعبد. كان ﷺ ينقل اللبن والحجارة ويحفر مع الناس ويرتجز معهم: "اللهم لا عيش إلا عيش الآخرة، فاغفر للأنصار والمهاجرة." وكانت في ذلك رسالة إنسانية رفيعة أن الكرامة في العمل والزعيم الحق من يعمل مع شعبه.\n\nوكان المسجد النبوي أول مؤسسة شاملة في الإسلام بمعنى الكلمة: فيه تُقام الصلوات الخمس وصلاة الجمعة، ومنه يُصدر القضاء ويُعقد الشورى وتُستقبل الوفود ويُعلَّم القرآن والفقه. وأُقيمت له ظُلّة يأوي تحتها أهل الصفّة من فقراء المسلمين الذين لا مأوى لهم فكانوا أول دار للإيواء الاجتماعي في الإسلام.',
