    fullDescription: 'بعد الاستقرار في المدينة المنورة وبناء المسجد النبوي، أقدم النبي ﷺ على إجراء تاريخي فريد لم تعرف له الشعوب نظيراً: المؤاخاة بين المهاجرين والأنصار في دار أنس بن مالك رضي الله عنه. فجمع نحو خمسة وأربعين رجلاً من المهاجرين ومثلهم من الأنصار، وقرن بين كل مهاجر وأنصاري يتشابهان في الطبع والمنزلة.\n\nوكانت هذه المؤاخاة في أول أمرها مؤاخاة فعلية شاملة تمتد إلى التوارث: إذ كان المهاجر يرث أخاه الأنصاري ويرثه كأنهما من صلب واحد. فأوجد النبي ﷺ بذلك حلاً عبقرياً للأزمة الاقتصادية للمهاجرين الذين تركوا أموالهم وديارهم في مكة وقدموا إلى المدينة لا يملكون شيئاً.\n\nوكان من أجمل مشاهد هذه المؤاخاة ما جرى بين سعد بن الربيع الأنصاري وعبد الرحمن بن عوف المهاجر؛ إذ قال له سعد: "أنا أكثر الأنصار مالاً فأقسم مالي نصفين، ولي امرأتان فانظر أعجبهما إليك فأطلّقها لك." فأجابه عبد الرحمن بنبل رفيع: "بارك الله لك في أهلك ومالك، دلّني على السوق." فذهب إلى السوق وتاجر ذلك اليوم فربح وعاد بسمن وأقط.\n\nثم نسخ الله لاحقاً التوارث بين الأخوين بعد نزول آيات المواريث، وقال تعالى: ﴿وَأُولُو الْأَرْحَامِ بَعْضُهُمْ أَوْلَىٰ بِبَعْضٍ﴾ فصار كلّ فريق يرث أهله. وبقيت المؤاخاة رابطاً روحياً وإنسانياً دلّ على أن الإسلام يُنشئ وشائج الأخوة الحقيقية التي تتجاوز الدم والقبيلة.',
