    fullDescription: 'لمّا استقرّ المسلمون في المدينة المنورة وتهيّأوا لإقامة شعائرهم الجماعية، واجهوا تساؤلاً عملياً: كيف يُنادى الناس إلى الصلاة؟ فتشاور النبي ﷺ مع أصحابه: اقترح بعضهم البوق كما يفعل اليهود، وبعضهم الناقوس كما يفعل النصارى، وبعضهم النار كما يفعل المجوس. فلم يَرتضِ النبي ﷺ شيئاً من ذلك إذ أراد الله أن يكون النداء للصلاة متميزاً فريداً لهذه الأمة.\n\nفأرى الله سبحانه عبدَه عبدالله بن زيد الأنصاري في منامه رجلاً يُعلّمه ألفاظ الأذان بصوت رفيع مُرتّل. فهبّ من نومه مسرعاً وجاء إلى النبي ﷺ يحكي رؤياه. فقال ﷺ: "إن هذه لرؤيا حقٌّ إن شاء الله." وكان عمر بن الخطاب رضي الله عنه قد رأى مثلها في ليلته فلم يسبق إلى إخبار النبي ﷺ. فأمر النبيُّ ﷺ بلالَ بن رباح رضي الله عنه أن يُعلَّم الألفاظ ويُؤذّن بها لأنه "أندى صوتاً".\n\nوصعد بلال رضي الله عنه أعلى سطح قرب المسجد ونادى بأجمل وأعمق نداء سمعته المدينة: "الله أكبر الله أكبر، أشهد أن لا إله إلا الله..." وكان في هذا المشهد دلالة إلهية عميقة: رجل كان يُعذَّب في مكة ويُرغَم على البراءة من "أحد أحد" أصبح الصوت الأعلى في الإسلام يُنادي بالتوحيد من أعلى نقطة.\n\nوقد فرح المسلمون بالأذان فرحاً عظيماً، وخرجوا من بيوتهم يستجيبون للنداء المبارك. وأصبح الأذان منذ تلك اللحظة شعار الإسلام الأبدي الذي تُرفع أصواته خمس مرات في اليوم في كل مكان من الأرض حيث يُقيم المسلمون، وكأن الدنيا لا تتوقف عن الإعلان بوحدانية الله وشهادة رسوله الكريم.',
