    fullDescription: 'ما إن استقرّ النبي ﷺ في المدينة المنورة حتى أدرك أن بناء الدولة يحتاج إلى أكثر من مسجد ومؤاخاة؛ يحتاج إلى إطار قانوني يُنظّم العلاقات بين مكوّنات المجتمع المتعدد الأديان والقبائل. فأقدم على كتابة وثيقة تاريخية فريدة عُرفت بالصحيفة المدنية أو صحيفة المدينة، وتضمّنت نحو سبعة وأربعين بنداً تُشكّل دستوراً حقيقياً لأول دولة مدنية في التاريخ.\n\nنصّت الوثيقة في أساسها على أن المسلمين المهاجرين والأنصار وسائر من انضمّ إليهم أمةٌ واحدة متمايزة عن سائر الناس، وأن على اليهود من بني عوف وبني قينقاع وسائر القبائل أن يتعاملوا وفق هذه الوثيقة. فلليهود دينهم وللمسلمين دينهم، وعلى الفريقين أن يتعاونوا في الدفاع عن المدينة وألا يخذل أحدهم الآخر.\n\nوجعلت الوثيقة من النبي ﷺ المرجع الأعلى في حسم كل خلاف يقع بين الأطراف الموقّعة، وهو ما يُعادل رئاسة الدولة بمفهومها الحديث. كما نصّت على أن يثرب حرم على أهلها لا يُؤذَى فيها أحد، وأن من اعتدى على أحد من أهل هذه الوثيقة يُعامَل معاملة العدو.\n\nوتُعدّ هذه الصحيفة أقدم وثيقة دستورية مكتوبة تُنظّم مجتمعاً تعددياً في التاريخ البشري المدوَّن، إذ سبقت الإعلانات الغربية لحقوق الإنسان بأكثر من ألف عام. وقد تجلّت فيها عبقرية النبي ﷺ السياسية التي أحكمت إطاراً يُتيح للإسلام أن ينمو ويتوطّد دون أن يُضطرّ في البداية إلى مواجهة الجميع في وقت واحد.',
