    description:
      'كان النبي ﷺ يُصلّي نحو بيت المقدس منذ بداية الإسلام. وكان يرفع وجهه إلى السماء يتمنى أن تُحوَّل القبلة إلى الكعبة المشرفة. فأنزل الله: ﴿فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ﴾. وجاء الأمر وسط الصلاة: كان النبي ﷺ يُصلي الظهر في مسجد بني سلمة، فاستدار في أثناء الصلاة نحو الكعبة واستدار الصفوف معه — فسُمّي المسجد "ذا القبلتين". وفرح المسلمون فرحاً عظيماً، بينما قال اليهود والمنافقون: ما ولّاهم عن قبلتهم التي كانوا عليها؟ فأنزل الله رداً حاسماً.',
    fullDescription: 'منذ بداية الإسلام في مكة، كان النبي ﷺ يتوجّه في صلاته نحو بيت المقدس. وقد استمر على ذلك سبعة عشر شهراً أو ستة عشر شهراً بعد الهجرة إلى المدينة. وكان ﷺ كثيراً ما يرفع طرفه إلى السماء يترقّب الأمر الإلهي بتحويل القبلة إلى الكعبة المشرفة قبلة أبيه إبراهيم، فعلم الله ذلك من قلبه وأشار إليه في قوله: ﴿قَدْ نَرَىٰ تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ﴾.\n\nوفي منتصف صلاة الظهر في مسجد بني سلمة بالمدينة، نزل الأمر الإلهي فجأةً: ﴿فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ﴾. فاستدار النبي ﷺ في أثناء الصلاة من بيت المقدس إلى الكعبة، واستدار المأمومون خلفه فتبدّل وجه الصفوف في خضم الصلاة دون إبطالها. ففرح المسلمون أيّما فرح، وسُمّي المسجد الذي جرى فيه هذا الحدث التاريخي بمسجد القبلتين.\n\nأما اليهود والمنافقون فقد اعترضوا واستنكروا قائلين: ما ولّاهم عن قبلتهم التي كانوا عليها؟ فتنبّأ القرآن الكريم بهذا الاعتراض قبل حدوثه وردّ عليه في آنٍ واحد: ﴿سَيَقُولُ السُّفَهَاءُ مِنَ النَّاسِ مَا وَلَّاهُمْ عَن قِبْلَتِهِمُ الَّتِي كَانُوا عَلَيْهَا قُل لِّلَّهِ الْمَشْرِقُ وَالْمَغْرِبُ﴾.\n\nوكان في تحويل القبلة دلالات عديدة: إعلان استقلالية الأمة المسلمة عن اليهودية والنصرانية، وتأكيد صلتها بإبراهيم عليه السلام باني الكعبة المشرفة، وتكريم لإجابة الله لتمنّي نبيّه بلا لفظ بل بتوجيه رباني مباشر.',
    verse: 'فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ ۚ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ',
