    description:
      'في شهر شعبان من السنة الثانية للهجرة نزلت آيات صيام رمضان في سورة البقرة. كان المسلمون يصومون عاشوراء من قبل فلما فُرض رمضان صار اختيارياً. نزل الفرض تدريجياً: أولاً التخيير بين الصيام والفدية، ثم الفرض العيني على كل مسلم قادر. وكان أول رمضان يصومه المسلمون هو رمضان السنة الثانية للهجرة — ثمانية عشر يوماً قبل غزوة بدر. فصاموا رمضان وخرجوا لبدر وانتصروا فكان الصيام أول تهيئة روحية لأول انتصار عسكري.',
    fullDescription: 'في شهر شعبان من السنة الثانية للهجرة نزلت آيات فرض صيام رمضان في سورة البقرة، وكانت الثالثة من الفرائض الكبرى التي فُرضت في المدينة بعد الهجرة إثر الصلاة والزكاة. وكان المسلمون قبل ذلك يصومون يوم عاشوراء الذي كان واجباً ثم أصبح بعد فرض رمضان سنّةً مستحبة.\n\nجاء تشريع الصيام بالتدرج الرحيم الذي هو منهج القرآن الكريم في التكليف: فأنزل الله أولاً الآية التي تُخيّر المسلم بين الصوم وبين إطعام مسكين فديةً، ثم نزل الفرض العيني القاطع: ﴿فَمَن شَهِدَ مِنكُمُ الشَّهْرَ فَلْيَصُمْهُ﴾. فأصبح صيام رمضان ركناً من أركان الإسلام الخمسة ركيزةً تربوية سنوية لتزكية النفس وتقوية الإرادة.\n\nوكان أول رمضان صامه المسلمون رمضان السنة الثانية للهجرة قبل غزوة بدر الكبرى بأسابيع معدودة. فصاموا شهرهم واستقوا من معين الإيمان والتقوى، ثم خرجوا إلى بدر في السابع عشر من رمضان فانتصروا على عدوّهم المتعجرف رغم قلّة عددهم وعدتهم. فكان صيام رمضان وبدر دليلاً على أن القوة الروحية تسبق القوة المادية وتُمكّن منها.\n\nوقد وصف النبي ﷺ الصيام بأنه جُنّة وأنه لله وهو يُجزي به، مُعلناً أن العبادة التي لا يطّلع عليها أحد ولا يمكن أن يُتحقّق منها إلا بالله هي من أخلص العبادات وأعظمها قرباً من الله تبارك وتعالى.',
    verse: 'يَا أَيُّهَا الَّذِينَ آمَنُوا كُتِبَ عَلَيْكُمُ الصِّيَامُ كَمَا كُتِبَ عَلَى الَّذِينَ مِن قَبْلِكُمْ لَعَلَّكُمْ تَتَّقُونَ',
