    fullDescription: 'في السابع عشر من رمضان من السنة الثانية للهجرة، دارت غزوة بدر الكبرى التي سمّاها القرآن الكريم "يوم الفرقان"؛ إذ كانت الفارقة بين الحق والباطل وبين الإسلام والشرك. خرج النبي ﷺ بثلاثة عشر وثلاثمئة من أصحابه ـ فيهم اثنان وسبعون مهاجراً والباقون أنصار ـ في أضعف تجهيز عسكري: لم تكن معهم إلا سبعون ناقة وفرسان.\n\nوفي مواجهة ألف مقاتل من قريش جاؤوا بعتادهم وزهوهم وقرّاراتهم، وقف النبي ﷺ في الليل يدعو ربّه بدعاء بلغ أعماق العرش: "اللهم أنجز لي ما وعدتني، اللهم آتِ ما وعدتني، اللهم إن تهلك هذه العصابة لا تُعبد في الأرض." ولم يزل يدعو وأبو بكر يقول له: "يا رسول الله حسبك مناشدتك ربّك، فسيُنجز لك ما وعدك." فنزل الملائكة بإذن الله تقاتل مع المسلمين.\n\nوسارت المعركة بأمر الله في صالح المؤمنين؛ فقُتل أبو جهل زعيم الكفر الأول وصناديد قريش كعتبة وشيبة وغيرهم، وبلغ قتلى المشركين سبعين وأسراهم سبعين، في حين لم يستشهد من المسلمين إلا أربعة عشر شهيداً. وكان ذلك نصراً لم يُشهد مثله في تاريخ المواجهات العسكرية بمثل هذا الفارق.\n\nوفي أعقاب بدر سنّ النبي ﷺ نظاماً إنسانياً للتعامل مع الأسرى؛ إذ جعل فداء كل أسير أن يُعلّم عشرة من أبناء المسلمين القراءة والكتابة. فكان التعليم ثمناً للحرية في سابقة إنسانية رفيعة تدلّ على أن الإسلام يُقدّم العلم على الانتقام.',
