    fullDescription: 'كان بنو قينقاع إحدى قبائل يهود المدينة الثلاث، وكانوا أهل قوة وحِرَف وتجارة؛ إذ كانوا صاغةً وحدادين يعيشون في سوق من أكبر أسواق يثرب. وقد وقّعوا مع النبي ﷺ الصحيفة المدنية وعهدوا بعدم الاعتداء والتعاون في الدفاع عن المدينة، غير أنهم بعد انتصار بدر بدأوا يُبدون تبجّحاً ويُلقون تحرشات بالمسلمين.\n\nكانت القشة التي قصمت الظهر أن رجلاً من بني قينقاع أهان امرأةً مسلمةً في السوق، فثار مسلم للدفاع عنها فقتل اليهودي فقتله يهود قصاصاً. عندها جمع النبي ﷺ بني قينقاع وذكّرهم بصلح الحديبية وما وقّعوه من عهود، وحذّرهم من مغبة النقض. فردّوا بغرور واستهانة: "لا يغرّك أنك أصبت قوماً لا علم لهم بالحرب، أما والله لو قاتلتنا لعلمتَ أننا نحن الرجال."\n\nفحاصرهم النبي ﷺ في حصونهم خمسة عشر يوماً حتى نزلوا على حكمه. وفي اللحظة التي أراد النبي ﷺ فيها معاملتهم بما اقتضته جريمة نقض العهد، تشبّث بهم عبدالله بن أُبيّ ابن سلول زعيم المنافقين وألحّ إلحاحاً شديداً في طلب العفو عنهم لأنهم كانوا حلفاءه. فقبل النبي ﷺ الشفاعة لكن بشرط الإجلاء من المدينة.\n\nوخرج بنو قينقاع بأموالهم ومتاعهم إلى الشام فتفرّقوا فيها. وكانت هذه أول تطبيق عملي لمبدأ أن العهد الذي يُنقض يُسقط الحماية التي كفلها له الصلح.',
