    fullDescription: `غزوة أحد من أعظم المحطات التربوية في تاريخ الإسلام؛ إذ لم تكن مجرد معركة بين المسلمين والمشركين، بل كانت درساً ربانياً عميقاً في معنى الطاعة والثبات على الأمر وعواقب المخالفة.

خرج النبي ﷺ في شوال من السنة الثالثة للهجرة بسبعمئة صحابي، وقبيل المعركة نصب خمسين رامياً على جبل عينين وأمرهم أمراً قاطعاً: لا تتركوا مواضعكم وإن رأيتمونا نُنهب ولا وإن رأيتمونا نُقتل. فلما انهزمت قريش في بداية المعركة انساق أكثر الرماة وراء الغنائم وتركوا مواضعهم، فالتفّ فرسان خالد بن الوليد من الخلف وأوقعوا بالمسلمين ضربة قاسية.

جُرح النبي ﷺ في وجهه الشريف وكُسرت رباعيته، وشاع في المسلمين نبأ مقتله فوقع الهلع. غير أن ثلة من الأبطال ثبتوا وأحاطوا به يذودون عنه بأنفسهم؛ من بينهم أنس بن النضر الذي قال: إن كان محمد قد مات فرب محمد لم يمت، فخاض المعركة وحيداً حتى استشهد وفي جسده سبعون ضربة.

استشهد في أحد سبعون صحابياً في مقدمتهم حمزة بن عبد المطلب عم النبي ﷺ. وقف النبي على جسد عمّه وعيناه تفيضان دمعاً وقال: لن أُصاب بمثلك أبداً. ثم نزل قرآن يُعلّم الأمة أن الهزيمة كانت بسبب المعصية ويُبشّر بأن الشهداء أحياء عند ربهم يُرزَقون. وعاد المسلمون من أحد بجراحات في الأجساد لكنهم عادوا أكثر نضجاً وفهماً لمعنى الطاعة والتوكل الصحيح.`,
