    fullDescription: `فتح مكة في العشرين من رمضان السنة الثامنة الهجرية كان اليوم الأعظم في تاريخ الإسلام—يوم عاد النبي ﷺ إلى الأرض التي وُلد فيها وعُذِّب وأُخرج منها، فاتحاً لا مُنتقماً، راحماً لا قاهراً.

نقضت قريش صلح الحديبية بإعانة حلفائها على مهاجمة حلفاء المسلمين. فجهّز النبي ﷺ جيشاً لم تر الجزيرة مثله: عشرة آلاف مقاتل يسير في صمت مطبق وسرية تامة. خرج إليه أبو سفيان زعيم قريش فأسلم وأعطاه النبي ﷺ أماناً لمن دخل بيته أو دخل المسجد الحرام أو أغلق بابه.

دخل النبي ﷺ مكة خاشعاً لله، رأسه منحنية على ناقته تواضعاً. أمر الجيش بالدخول دون قتال إلا من أشهر سلاحاً. وعند فتح الكعبة طاف بها وهو يُكبّر وحطّم الأصنام وهو يتلو: ﴿جَاءَ الْحَقُّ وَزَهَقَ الْبَاطِلُ إِنَّ الْبَاطِلَ كَانَ زَهُوقاً﴾.

لما وقف قريش بين يديه—وهم الذين عذّبوه وأخرجوه وقتلوا أصحابه—سألهم: ما تظنون أني فاعل بكم؟ قالوا: خيراً، أخٌ كريم وابن أخ كريم. فقال كلمته الخالدة: اذهبوا فأنتم الطلقاء. عفا عن الجميع عفواً عاماً، وكان يوم المرحمة لا يوم المجزرة.`,
